QFrame* surface(QWidget*parent){auto*frame=new QFrame(parent);frame->setObjectName("jobsSurfacePanel");return frame;}
QString requestKey(){return QUuid::createUuid().toString(QUuid::WithoutBraces).remove('-').toLower();}
QString changeSummary(const savor::db::PredicateAuthoringRevisionReceipt&r){if(r.identity_created)return QStringLiteral("new object and semantic content");if(r.metadata_changed&&r.semantic_changed)return QStringLiteral("metadata and semantic content");if(r.metadata_changed)return QStringLiteral("metadata");if(r.semantic_changed)return QStringLiteral("semantic content");return QStringLiteral("no content");}
QString typeLabel(const TypeRef&type){if(type.is_named())return QString::fromStdString(type.named->canonical_id);static constexpr const char*labels[]={"Unit","True/false","U8","U16","U32","U64","I32","I64","F32","F64"};const auto ordinal=static_cast<std::size_t>(type.builtin);return ordinal<std::size(labels)?QString::fromLatin1(labels[ordinal]):QStringLiteral("Unknown");}
QString literalText(const LiteralValue&value){return std::visit([](const auto&item)->QString{using T=std::decay_t<decltype(item)>;if constexpr(std::is_same_v<T,UnitValue>)return{};else if constexpr(std::is_same_v<T,bool>)return item?QStringLiteral("true"):QStringLiteral("false");else if constexpr(std::is_arithmetic_v<T>)return QString::number(item);else return QStringLiteral("<typed value>");},value.payload);}

std::optional<LiteralValue> parseLiteral(QString text,const TypeRef&type,QString*error)
{
    text=text.trimmed();if(type.is_named()){if(error)*error=QStringLiteral("Fixed values require a scalar type.");return std::nullopt;}LiteralValue value{.type=type};bool ok=false;switch(type.builtin){case BuiltinType::Unit:value.payload=UnitValue{};return value;case BuiltinType::Bool:if(text.compare("true",Qt::CaseInsensitive)==0||text=="1")value.payload=true;else if(text.compare("false",Qt::CaseInsensitive)==0||text=="0")value.payload=false;else break;return value;case BuiltinType::U8:{const auto n=text.toUInt(&ok,0);if(ok&&n<=UINT8_MAX){value.payload=static_cast<std::uint8_t>(n);return value;}break;}case BuiltinType::U16:{const auto n=text.toUInt(&ok,0);if(ok&&n<=UINT16_MAX){value.payload=static_cast<std::uint16_t>(n);return value;}break;}case BuiltinType::U32:{const auto n=text.toULongLong(&ok,0);if(ok&&n<=UINT32_MAX){value.payload=static_cast<std::uint32_t>(n);return value;}break;}case BuiltinType::U64:{const auto n=text.toULongLong(&ok,0);if(ok){value.payload=static_cast<std::uint64_t>(n);return value;}break;}case BuiltinType::I32:{const auto n=text.toLongLong(&ok,0);if(ok&&n>=INT32_MIN&&n<=INT32_MAX){value.payload=static_cast<std::int32_t>(n);return value;}break;}case BuiltinType::I64:{const auto n=text.toLongLong(&ok,0);if(ok){value.payload=static_cast<std::int64_t>(n);return value;}break;}case BuiltinType::F32:{const auto n=text.toFloat(&ok);if(ok){value.payload=n;return value;}break;}case BuiltinType::F64:{const auto n=text.toDouble(&ok);if(ok){value.payload=n;return value;}break;}}if(error)*error=QStringLiteral("The value does not fit %1.").arg(typeLabel(type));return std::nullopt;
}

const PredicateAuthoringSemanticInputV2* semanticForWitness(const PredicateAuthoringCatalogV2&catalog,const PredicateWitness&witness)
{
    const auto found=std::ranges::find_if(catalog.semantic_inputs,[&](const auto&input){return input.witness_name==witness.name&&input.value_type==witness.value_type;});return found==catalog.semantic_inputs.end()?nullptr:&*found;
}

