void PredicateAuthoringEditor::configureRefresh()
{
    refreshPipeline_=new savorqt::gui::DatabaseProjectionController<int,CatalogRefreshData>(this);refreshPipeline_->setAutoRefreshEnabled(false);refreshPipeline_->setRequestBuilder([](savorqt::gui::RefreshReason)->std::optional<int>{return 0;});refreshPipeline_->setLoadAndPrepare([](int){CatalogRefreshData data;data.catalog=savorqt::db::SavorDbAuthoringService::GetPredicateAuthoringCatalog();data.definitions=savorqt::db::SavorDbAuthoringService::ListPredicateDefinitionRevisions(std::string("PUBLISHED"),{},500);if(data.definitions.ok)for(const auto&summary:data.definitions.value.items){const auto detail=savorqt::db::SavorDbAuthoringService::GetPredicateDefinitionRevision(summary.predicate_definition_revision_id);if(detail.ok)data.definitionSnapshots.push_back(detail.value);}return savorqt::gui::ProjectionLoadResult<CatalogRefreshData>::Ok(std::move(data));});refreshPipeline_->setApply([this](const CatalogRefreshData&data,savorqt::gui::RefreshReason,const savorqt::gui::RefreshStatus&){applyCatalog(data);});refreshPipeline_->setApplyError([this](const QString&error,savorqt::gui::RefreshReason,const savorqt::gui::RefreshStatus&){postStatus(error,StatusToast::Severity::Error);});refreshPipeline_->setActive(true);
}
void PredicateAuthoringEditor::requestRefresh(){if(refreshPipeline_)refreshPipeline_->requestRefresh(savorqt::gui::RefreshReason::Manual);}

void PredicateAuthoringEditor::applyCatalog(const CatalogRefreshData&data)
{
    if(!data.catalog.ok||!data.definitions.ok){validationLabel_->setText(QString::fromStdString((!data.catalog.ok?data.catalog.error:data.definitions.error).message));return;}

    std::vector<QString> sourceDrafts;
    const auto priorDefinitionId = selectedDefinition_
        ? std::optional<std::int64_t>(selectedDefinition_->predicate_definition_revision_id)
        : std::nullopt;
    const auto priorScroll = bindingScroll_ ? bindingScroll_->verticalScrollBar()->value() : 0;
    if(mode_==ObjectKind::ExecutionBinding){
        sourceDrafts.reserve(bindingCards_.size());
        for(const auto&card:bindingCards_)
            sourceDrafts.push_back(card.value ? card.value->text() : QString{});
    }

    catalog_=data.catalog.value;ruleEditor_->setCatalog(catalog_);publishedDefinitions_=data.definitions.value.items;publishedDefinitionSnapshots_=data.definitionSnapshots;
    const auto selected=requestedDefinitionRevisionId_.value_or(definitionCombo_->currentData().toLongLong());
    {const QSignalBlocker blocker(definitionCombo_);definitionCombo_->clear();for(const auto&definition:publishedDefinitionSnapshots_){definitionCombo_->addItem(QStringLiteral("%1 — revision %2").arg(QString::fromStdString(definition.name)).arg(definition.definition.revision),definition.predicate_definition_revision_id);if(definition.predicate_definition_revision_id==selected)definitionCombo_->setCurrentIndex(definitionCombo_->count()-1);}}
    requestedDefinitionRevisionId_.reset();if(definitionCombo_->currentIndex()<0&&!publishedDefinitionSnapshots_.empty())definitionCombo_->setCurrentIndex(0);
    validationLabel_->setText(QStringLiteral("Authoring catalog ready: %1 Battle values, %2 data inputs, and %3 hooks.").arg(catalog_.value_recipes.size()).arg(catalog_.semantic_inputs.size()).arg(catalog_.hooks.size()));
    if(pendingDefinitionLoad_){const auto pending=*pendingDefinitionLoad_;pendingDefinitionLoad_.reset();loadDefinition(pending,pendingLoadDuplicate_);}
    else if(pendingBindingLoad_){const auto pending=*pendingBindingLoad_;pendingBindingLoad_.reset();loadExecutionBinding(pending,pendingLoadDuplicate_);}
    else if(mode_==ObjectKind::ExecutionBinding){
        rebuildBindingCards();
        if(priorDefinitionId&&selectedDefinition_&&*priorDefinitionId==selectedDefinition_->predicate_definition_revision_id&&sourceDrafts.size()==bindingCards_.size()){
            for(std::size_t row=0;row<bindingCards_.size();++row)
                if(bindingCards_[row].value)
                    bindingCards_[row].value->setText(sourceDrafts[row]);
        }
        if(bindingScroll_)bindingScroll_->verticalScrollBar()->setValue(priorScroll);
    }
}

